/**
 * REBOUND — shared contract (M1, "v1, honest").
 *
 * This file is the single source of truth between the workstreams:
 *   - src/model.ts    pure simulation core (implements ModelApi, no DOM)
 *   - src/content.ts  data for sectors, ages, applications, upgrades, levers… (exports `content: Content`)
 *   - src/ui/*        DOM interface (reads Derived and the views, calls ModelApi)
 *
 * Do not edit this file from a workstream. If the contract is wrong or missing something,
 * work around it locally and report it in your final message.
 *
 * Words
 *   - SECTOR (code) = one service + resource economy with its applications, efficiency path, pressure and levers.
 *     It opens at some point in a run and keeps running beside the others. ON SCREEN a sector is an "Industry"
 *     (plural "Industries"). No player-facing text says "sector" or "era" for this unit.
 *   - AGE (code and screen) = a period of the calendar: a year span, the page theme, and the sectors that belong to it.
 *     An age will later own a prestige layer (Reckoning / Treaty / Long Now); nothing here designs that yet.
 *   - v1 called both of these "era". The full old → new mapping is in design/m1-contract-notes.md.
 *
 * Conventions
 *   - All rates are per real second of play. `dt` is in seconds.
 *   - "Model years" = seconds × YEARS_PER_SECOND. Every timer, streak, decade and budget runs on model years.
 *     The *calendar* year shown to the player (Derived.year) is a separate, cosmetic quantity (see AgeDef.yearSpan).
 *   - ModelApi functions are PURE: never mutate the state passed in, always return a new state.
 *     No Date.now(), no Math.random() (use state.seed with a small deterministic PRNG if needed).
 *   - Money is "£" in every sector for simplicity.
 *   - Optional content fields state their default. Search for "M1 CHANGE" for semantics that differ from v1.
 *   - Nothing in the contract assumes a number of sectors or ages: iterate content.sectorOrder and content.ages.
 *
 * Forward compatibility (see design/roadmap.md): per-sector run state (budget, levers) lives in SectorState /
 * LeverState so that M5 can hold one copy per region; meta-level choices (loadout, slots) live in MetaState. The
 * unions below (EffectDef, StatKey, LeverRecycle, HeadlineKey) will grow; code switching on them must have a default
 * branch that ignores unknown members. Shared stocks and `feeds` (M4) are not here yet.
 */

/** M1 CHANGE: was the five-member union EraId. Ids are content-defined, e.g. 'steam'. */
export type SectorId = string;
export type AgeId = string;

/** Model years that pass per real second (3 a minute). Drives every streak, budget and timer. */
export const YEARS_PER_SECOND = 0.05;
/** Model years of unbroken decoupling (see SectorDerived.decoupling) needed for a sector's Steady State. */
export const STEADY_STATE_YEARS = 50;
/** Calendar year used only when content has no ages (fallback clock: START_YEAR + run time × YEARS_PER_SECOND). */
export const START_YEAR = 1780;
/** Past its age's last year, the calendar advances at this fraction of the normal rate (until a later age begins). */
export const CALENDAR_LATE_RATE = 0.1;
/** A stock reserve counts as exhausted at or below this fraction of reserveMax (0.2%): the run must end. */
export const EXHAUSTED_BELOW = 0.002;
/** R may exceed the budget line by this fraction and still count as within budget (solver noise, a cap at 1.0). */
export const BUDGET_TOLERANCE = 0.005;
/** Horizon of the "this decade" projection on upgrade cards, in model years (200 s). */
export const PROJECTION_YEARS = 10;
/** tick() never advances more than this many seconds per call; longer gaps go through fastForward(). */
export const MAX_TICK_SECONDS = 60;
/**
 * Save format version. M1 CHANGE: 2.
 * Migration rule (implemented in ModelApi.deserialize):
 *   - version > SAVE_VERSION → null (a save from the future is refused).
 *   - version 1 (or missing) → migrated as follows, then stamped 2:
 *       top-level `eras` → `sectors` (same keys: the v1 ids 'steam' … 'code' are kept as sector ids); every
 *         `history[i].eras` → `history[i].sectors`; every `news[i].era` → `news[i].sector`;
 *         meta.lastRun.eras → .sectors and .causeEra → .causeSector;
 *       meta.steadyEras → meta.steadySectors; run.steadyEras → run.steadySectors;
 *       meta.furthestEra (an index n) → meta.sectorsOpened = { s: true } for the first n ids of content.sectorOrder;
 *       meta.institutions: `true` → level 1;
 *       meta.slots = max(content.global.startingSlots ?? 2, number of owned institutions);
 *       meta.loadout = every owned institution id still in content, in content order (v1 players are grandfathered:
 *         everything they owned stays seated);
 *       meta.backfiredSectors = { s: true } for every sector whose current-run state has backfired true;
 *       every SectorState: etaAtBase kept if present (the v1 model stored it as an extra), else baseD / baseR, else
 *         baseEta; serviceDelivered 0; decadesWithin []; steadyYears 0; budget null, EXCEPT that a sector with an
 *         active cap lever whose ref > 0 gets budget = { r0: ref, since: state.time, drawnYear: current calendar year };
 *       steadyYearsAll 0; run.decoupledYears 0 (the v1 trend-based definitions do not carry over);
 *       run.wellbeingYears, run.yearsAtTarget, run.budgetDecades 0; run.firstBackfires {};
 *       lever levels clamped to the lever's maxLevel; recycle left unset (default applies);
 *       meta.lastRun's new optional fields stay absent.
 *     Sectors in the save but not in content are dropped; sectors in content but not in the save are rebuilt closed.
 *   - Any missing field of a version-2 save is rebuilt from a fresh state (deep merge), as in v1.
 * The UI may keep its localStorage key; deserialize does the migration.
 */
export const SAVE_VERSION = 2;

/* ------------------------------------------------------------------ */
/* CONDITIONS (data-only "when X")                                     */
/* ------------------------------------------------------------------ */

export type CmpOp = '<' | '<=' | '>' | '>=';

/**
 * Statistics a Cond can read. Scope:
 *   - Global (sector/app ignored): 'time' (run seconds), 'year' (calendar, Derived.year), 'wellbeing', 'population',
 *     'capital', 'mandate', 'reckonings' (meta.reckonings), 'steadyYearsAll', 'clicks' (run.clicks).
 *   - Sector (`sector` required; if the sector is absent from content, closed, or the value is null, the leaf is
 *     FALSE): 'etaFold', 'rFold', 'frontierFold', 'peakRFold' (SectorState.peakR / baseR), 'rebound',
 *     'resourceUse' (R), 'demand' (D), 'servicePrice' (p_s), 'serviceDelivered', 'reserveFraction', 'pressureFraction',
 *     'crises' (SectorState.crisesFired), 'steadyYears', 'budgetDecades' (decadesWithin.length),
 *     'withinBudget' (1 or 0), 'appsFounded' (count of founded applications).
 *   - Application (`app` required, sector inferred from the app; FALSE if that sector is closed):
 *     'adoption', 'appDemand' (AppDerived.demand).
 * Every value is the one Derived/SectorDerived/AppDerived would report for the same state.
 */
export type StatKey =
  | 'time' | 'year' | 'wellbeing' | 'population' | 'capital' | 'mandate' | 'reckonings' | 'steadyYearsAll' | 'clicks'
  | 'etaFold' | 'rFold' | 'frontierFold' | 'peakRFold' | 'rebound' | 'resourceUse' | 'demand' | 'servicePrice'
  | 'serviceDelivered' | 'reserveFraction' | 'pressureFraction' | 'crises' | 'steadyYears' | 'budgetDecades'
  | 'withinBudget' | 'appsFounded'
  | 'adoption' | 'appDemand';

/**
 * A data-only condition, evaluated by the core against a state (and the flows it derives).
 *   - { stat, op, value }: compare a statistic (see StatKey for scope rules).
 *   - { owns: id }: id is looked up across all content (ids are unique game-wide) and is true when:
 *       upgrade level ≥ 1 this run · application founded this run · lever level ≥ 1 · institution level ≥ 1 (owned,
 *       seated or not) · know-how level ≥ 1 · achievement earned. Unknown id → false (the content lint catches it).
 *   - { flag }: state.flags[flag] === true ('revealed', 'won'; unknown flag → false).
 *   - all / any / not: logical combinators. Empty `all` is true, empty `any` is false.
 * `label` is the player-facing wording of this node ("Own the Separate condenser"), used by checklists
 * (Derived.nextSector). Content should label every direct child of an unlock's top-level `all`.
 * Unknown leaf shapes evaluate false.
 */
export type Cond = (
  | { stat: StatKey; sector?: SectorId; app?: string; op: CmpOp; value: number }
  | { owns: string }
  | { flag: string }
  | { all: Cond[] }
  | { any: Cond[] }
  | { not: Cond }
) & { label?: string };

/* ------------------------------------------------------------------ */
/* CONTENT (static data, never changes during play)                    */
/* ------------------------------------------------------------------ */

export interface Content {
  /** M1 CHANGE (was `eras`): every sector, keyed by id. */
  sectors: Record<SectorId, SectorDef>;
  /**
   * M1: the order sectors are listed, iterated and (by default) unlocked in. Contains every key of `sectors` exactly
   * once. sectorOrder[0] is open at the start of every run.
   */
  sectorOrder: SectorId[];
  /** M1: the ages, in calendar order. Every sector belongs to exactly one age (AgeDef.sectors). */
  ages: AgeDef[];
  upgrades: UpgradeDef[];
  levers: LeverDef[];
  knowhow: KnowhowDef[];
  institutions: InstitutionDef[];
  achievements: AchievementDef[];
  /**
   * Broadsheet headline variants keyed by event (the fallback set). Placeholders substituted by the model:
   * `{sector}` sector name (on screen an industry), `{age}` age name, `{app}` application name, `{resource}`,
   * `{service}`, `{year}` calendar year (integer), `{n}` an event count (the decade number for 'decade', the crisis
   * number for 'crisis', else empty). Variant choice is deterministic from state.seed, time and the news count.
   * M1 balance: substitution is case-aware. `{app}`, `{resource}` and `{service}` are common nouns: away from the start
   * of a sentence their first letter is lower-cased ("demand for coal"), unless the name starts with an acronym ("AI
   * models") — only the first letter is touched, so later proper nouns survive. `{age}` lower-cases a leading "The"
   * mid-sentence ("Welcome to the Coal Age"). `{sector}` is the proper name of an industry and is kept as authored.
   * A sentence starts at the beginning of the template or after . ! or ? and a space (opening quotes allowed).
   * Content should therefore author those names in sentence case with any proper noun after the first word.
   */
  headlines: Record<HeadlineKey, string[]>;
  /**
   * M1: sector-specific variants. When an event belongs to a sector and `sectorHeadlines[sector][key]` is a non-empty
   * array, it is used instead of `headlines[key]`. Default: absent (everything falls back to `headlines`).
   */
  sectorHeadlines?: Record<SectorId, Partial<Record<HeadlineKey, string[]>>>;
  global: GlobalParams;
}

/**
 * M1: a period of the calendar. The page theme belongs to the age; a sector adds only an accent.
 * Later an age may own a prestige layer (a field such as `layer` will be added then); nothing depends on that now.
 */
export interface AgeDef {
  id: AgeId;
  /** On screen: "The Coal Age", "The Great Acceleration"… */
  name: string;
  /** One line shown when the age begins. */
  tagline: string;
  /**
   * Calendar span [first, last]. last may be Infinity. Calendar of the age while any of its sectors is open:
   *   y = max( yearSpan[0] + T × YEARS_PER_SECOND,  max over its open sectors s of (s.firstYear ?? yearSpan[0]) + s.openFor × YEARS_PER_SECOND )
   *   with T = the largest openFor among its open sectors (time since the age began);
   *   if y > yearSpan[1]: y = yearSpan[1] + (y − yearSpan[1]) × CALENDAR_LATE_RATE.
   * Derived.year = max over ages with an open sector (so it never runs backwards when something opens).
   */
  yearSpan: [number, number];
  /**
   * Page theme key; the UI keeps a registry of looks. M1 looks: 'ledger', 'gaslight', 'chrome', 'terminal', 'agentic'.
   * Unknown keys fall back to the UI's default look.
   */
  theme: string;
  /** Sector ids that belong to (and can open in) this age, in display order. */
  sectors: SectorId[];
}

export interface GlobalParams {
  /** Starting capital of a fresh run. */
  startCapital: number;
  /**
   * Seconds of current income granted per manual click (the "sell power by hand" button).
   * Click value = clickFlat + clickSeconds × income per second (Derived.clickValue).
   */
  clickSeconds: number;
  /** Flat capital per click so the very first click does something. */
  clickFlat: number;
  /**
   * Population growth rate per second per point of wellbeing above subsistence. Population starts at 1.
   * Growth per second g(W), with W wellbeing, s = subsistence, mul = Π popGrowthMul effects:
   *   W < s:                       g = popGrowth · mul · (W − s) · 0.25            (decline at a quarter strength)
   *   W ≥ s, no demography:        g = popGrowth · mul · (W − s)                   (v1)
   *   W ≥ s, demography.W_t > s:   g = popGrowth · mul · (W − s) · max(0, 1 − ((W − s) / (W_t − s))²)
   * dN/dt = g · N. Each crisis multiplies N by (1 − crisisPopLoss). N never falls below 0.01.
   * With demography, growth peaks at W = s + (W_t − s)/√3 and stops at W ≥ W_t (the demographic transition).
   */
  popGrowth: number;
  /** Wellbeing (0–100 scale) below which population does not grow. */
  subsistence: number;
  /** Wellbeing the player must hold for decoupling (and so Steady State). Must be below demography.transitionWellbeing. */
  wellbeingTarget: number;
  /** Mandate per second per point of wellbeing above `mandateFloor`. */
  mandateRate: number;
  mandateFloor: number;
  /** Mandate granted by each Pressure crisis (the political window). */
  crisisMandate: number;
  /** Fraction of population lost in each Pressure crisis. */
  crisisPopLoss: number;
  /**
   * M1 CHANGE: Hindsight weights. See ModelApi.hindsightOnReckon and HindsightTerms; every term is ≥ 0.
   *   perWellbeingYear   × wellbeing-years (∫ max(0, W − subsistence) d(model years)) ÷ max(1, intensity)^intensityExponent
   *   intensityExponent  0 ignores how much was burnt; 1 divides by the run's average burn fold
   *   perBudgetDecade    × decades completed within budget this run (all sectors)
   *   perUnburnt         × Σ over open stock sectors of (share of reserve left) × min(1, yearsAtTarget / STEADY_STATE_YEARS)
   *   perFirstBackfire   × sectors whose FIRST-EVER backfire happened this run (failure teaches, once per sector)
   *   perSectorReached   × (sectors open at the Reckoning − 1)
   *   perSteadySector    × sectors that reached Steady State this run
   */
  hindsight: {
    perWellbeingYear: number;
    intensityExponent: number;
    perBudgetDecade: number;
    perUnburnt: number;
    perFirstBackfire: number;
    perSectorReached: number;
    perSteadySector: number;
  };
  /** Offline progress cap in seconds. */
  offlineCapSeconds: number;
  /**
   * M1: the demographic transition (see popGrowth). Default: absent = v1 linear growth with no ceiling.
   * transitionWellbeing W_t must exceed subsistence, and should exceed wellbeingTarget so a steady economy can hold
   * the target without growing.
   */
  demography?: { transitionWellbeing: number };
  /**
   * M1: budgets and Steady State (see SectorState.budget, SectorDerived.decoupling). Default when absent:
   * { budgetDeclinePerDecade: 0.05, decadeYears: 10, decadeEffects: [], firstSteadyEffects: [] }.
   *   budgetDeclinePerDecade  budgetR(t) = max(floor · r0, r0 · (1 − d)^(y / 10)), y = model years since drawn,
   *                           counted only until the line is HELD (BudgetState.heldAt). A sector may override.
   *                           M1 BALANCE CHANGE: the line declines until the sector reaches Steady State on it, then
   *                           holds level for the rest of the run (until redrawn). Steady State is earned by real
   *                           decline (50 streak years ≥ five decades of it); once earned it is keepable indefinitely.
   *   budgetFloor             M1 BALANCE: the line never falls below this fraction of r0. Default 0 (no floor).
   *   standingDrawYears       M1 BALANCE: an active cap with no budget (an institution's standing cap) draws its line
   *                           automatically only once the sector has been open this many model years (on the first step
   *                           with demand after that), so it is drawn across a grown economy rather than the opening
   *                           one. Default 0 (the first step with demand). A sector may override.
   *   decadeYears             streak length of one "decade within budget" (milestone). Default 10.
   *   decadeEffects           applied each time any sector completes a decade within budget (unless it overrides).
   *                           One-off effects pay at that moment; standing effects stay for the rest of the run, once
   *                           per decade earned (two decades of `wellbeingAdd 1` give +2).
   *   firstSteadyEffects      applied once, the first time EVER a given sector reaches Steady State (meta.steadySectors
   *                           flips true); typically `slotAdd`.
   */
  steady?: {
    budgetDeclinePerDecade: number;
    budgetFloor?: number;
    standingDrawYears?: number;
    decadeYears?: number;
    decadeEffects: EffectDef[];
    firstSteadyEffects?: EffectDef[];
  };
  /**
   * M1: levy (duty and cap permit) revenue routed by the 'treasury' recycle option. Default: { mandateShare: 0.1 }.
   * mandateShare of treasury-routed revenue becomes Mandate per second; the rest is general taxation and vanishes.
   * Levy revenue is never player income.
   */
  levy?: { mandateShare: number };
  /** M1: Institution seats a brand-new player has (MetaState.slots of a fresh meta). Default 2. */
  startingSlots?: number;
}

/** M1 CHANGE (was EraDef): one service + resource economy. On screen: an "Industry". */
export interface SectorDef {
  id: SectorId;
  name: string;            // "Steam"
  /** Display only ("1780–1870"). */
  years: string;
  /**
   * M1: calendar year this sector's own clock starts at when it opens (see AgeDef.yearSpan), so Light never opens in
   * "1810". Default: its age's yearSpan[0].
   */
  firstYear?: number;
  tagline: string;         // one line shown when the sector opens
  service: { name: string; unit: string };    // "Motive power", "hp"
  resource: { name: string; unit: string };   // "Coal", "tons"
  pressure: { name: string; crisisName: string }; // "Smog", "The Great Stink"
  /**
   * M1 CHANGE: the page theme moved to AgeDef.theme. `accent` is a small accent key the UI maps to a token set
   * (accent colour, pressure-weather tint) layered over the age's theme. Default: the age's own accent.
   */
  accent?: string;
  /**
   * M1 (transitional): full-theme override, used when this sector is selected. Lets the v1 looks ('gaslight' for
   * Light, 'agentic' for Code) survive inside a shared age until each age has its final look. Default: absent.
   * Expected to be removed when the ages get their final looks (M3–M4).
   */
  theme?: string;

  /* --- price side --- */
  /** p_0: base resource price. */
  basePrice: number;
  /** c: capital + labour cost per unit of service (before upgrades). Effective c = capCost × Π capCostMul. */
  capCost: number;
  /** m: the player's cut of spending on the service. Effective m = max(0, margin + Σ marginAdd). */
  margin: number;
  /** Starting efficiency η (service per unit resource). Usually 1. */
  baseEta: number;
  /**
   * Compute's twist. If > 0, η grows on its own by this exponential rate per second once the sector is open
   * (η = baseEta × Π etaMul × exp(autoEtaRate × openFor)). The player cannot switch it off.
   * Auto growth counts as efficiency gain: it is frozen out of the shadow solve like any other η gain.
   */
  autoEtaRate: number;

  /* --- resource side --- */
  /**
   * 'stock': a depletable reserve Q. p_r = basePrice × (reserveMax / Q)^alpha. Exhausted (forced Reckoning) once
   *          Q ≤ EXHAUSTED_BELOW × reserveMax (0.2%), not at exactly 0.
   * 'flow' : a renewable capacity per second (Code's attention). p_r = basePrice × (1 / (1 − u))^alpha
   *          where u = min(0.98, R / usableCapacity). Never runs out; just gets scarce; service above u = 0.98 is rationed.
   */
  resourceKind: 'stock' | 'flow';
  /** Q0 for 'stock'; capacity per second for 'flow'. Increased by reserveAdd effects (see EffectDef). */
  reserve: number;
  alpha: number;

  /* --- pressure side --- */
  /**
   * 'resource': P += R × intensity × dt  (smog, carbon)
   * 'service' : P += D × (1 − substituted share) × intensity × dt  (Code: every shipped feature adds to the code stock)
   * intensity = pressureIntensity × (1 − sharedLibs share). Then P decays: P ×= exp(−absorption × dt).
   */
  pressureSource: 'resource' | 'service';
  pressureIntensity: number;
  /** Fraction of P absorbed per second (plus absorptionAdd effects). 0 for Code (code never rots away on its own). */
  absorption: number;
  /** P at which the run collapses (forced Reckoning). */
  collapseAt: number;
  /** Crisis events fire the first time P crosses each of these fractions of collapseAt, e.g. [0.4, 0.7]. Ascending. */
  crisisAt: number[];
  /** Wellbeing points lost at P = collapseAt (scaled linearly below that). */
  pressureWellbeingCost: number;
  /**
   * Code's twist. Capacity eaten per unit of P per second (maintenance upkeep on the code stock).
   * effectiveCapacity = max(5% of capacity, capacity − P × pressureUpkeep); usable = effective × (1 − deletion share).
   * 0 elsewhere.
   */
  pressureUpkeep: number;

  /* --- wellbeing --- */
  /**
   * Weight of this service in wellbeing:
   *   W_s = wellbeingWeight × ln(1 + (D + D_div) / (N × wellbeingScale)) × defectFactor − pressureWellbeingCost × min(1, P / collapseAt)
   * D_div = (levy revenue of this sector routed to 'dividend') / p_s: the dividend counted as service it could buy.
   * defectFactor = 1 except in flow sectors (Code's unreviewed-work penalty, as v1).
   * W = max(0, Σ open sectors W_s + Σ wellbeingAdd effects).
   */
  wellbeingWeight: number;
  wellbeingScale: number;

  /* --- cross-sector links --- */
  /**
   * Indirect rebound. Money households save on this service is spent on another sector's.
   * Saturation of every application in `spill.to` is multiplied by
   *   1 + spill.rate × (1 − greenSpending share of this sector) × max(0, 1 − p_s / basePs)
   * (basePs = this sector's p_s when its baseline was recorded). Only while both are open.
   */
  spill?: { to: SectorId; rate: number };
  /** Code → Compute. Each unit of this sector's service adds this much service demand to `drawsOn.sector` (a price-proof floor). */
  drawsOn?: { sector: SectorId; perService: number };

  /* --- unlock --- */
  /**
   * sectorOrder[0] has no unlock and is open from the start. Any other sector opens on the first step at which ALL hold:
   *   - every sector in `after` is open (default: the sector before it in sectorOrder);
   *   - meta.reckonings ≥ minReckonings;
   *   - `when` evaluates true (M1: milestones that restraint does not block, e.g. an upgrade owned and an amount of
   *     service delivered);
   *   - only if `when` is ABSENT: the default predecessor's servicePrice < prevServicePriceBelow (DEPRECATED v1 gate;
   *     ignored whenever `when` is present).
   * A sector with no `unlock` (other than sectorOrder[0]) opens as soon as its predecessor is open.
   * Several sectors may open in the same step.
   */
  unlock?: { when?: Cond; minReckonings: number; after?: SectorId[]; prevServicePriceBelow?: number };

  /**
   * M1: per-sector overrides of GlobalParams.steady. Default: absent (global values).
   * declinePerDecade replaces budgetDeclinePerDecade; decadeEffects replaces the global decadeEffects for decades
   * this sector completes; budgetFloor and standingDrawYears replace the global ones (M1 balance).
   */
  steady?: { declinePerDecade?: number; decadeEffects?: EffectDef[]; budgetFloor?: number; standingDrawYears?: number };

  applications: ApplicationDef[];
}

export interface ApplicationDef {
  id: string;              // unique across the whole game, e.g. 'steam.mills'
  name: string;            // "Cotton mills"
  blurb: string;           // one line of flavour
  /** Small pictogram the UI draws (the UI owns a set of inline SVGs keyed by this). */
  icon: string;
  /** p_i: service price at which half of saturation is adopted. Effective p_i = halfPrice × Π halfPriceMul. */
  halfPrice: number;
  /**
   * S_i: demand at full saturation for population 1.
   * Effective S_i = N × saturation × AppState.satMul (sufficiency) × Π satMul effects × spill multiplier.
   */
  saturation: number;
  /** k_i: steepness (elasticity while the use is young). D_i = S_i / (1 + (p_s / p_i)^k_i). */
  steepness: number;
  /**
   * Frontier rebound. The application becomes *available* the first time p_s ≤ visibleBelow
   * (Infinity = from the start). The player then pays `foundCost` capital to found it.
   * Demand is zero until founded. foundCost 0 = founded automatically when available.
   */
  visibleBelow: number;
  foundCost: number;
  /**
   * Steam's twist: each unit of this application's demand adds this much to BOTH reserve and reserveMax per second.
   * Balance rule: keep reserveGainPerService × η × (this app's share of sector demand) < 1 at every reachable η, or the
   * app regenerates more coal than the sector burns and the reserve can never run out.
   */
  reserveGainPerService?: number;
  /** Motion's twist: demand never falls below this fraction of the application's own peak (lock-in). 0 = none. */
  lockIn?: number;
}

/**
 * Effects. Two families:
 *   - STANDING effects are modifiers in force while their source is held: an upgrade owned this run (× its level), a
 *     know-how node (× its level), a SEATED institution (each owned level's effects once), or a decade reward earned
 *     this run (× decades earned). They are recomputed, never written into state.
 *   - ONE-OFF effects ('mandateAdd', 'capitalAdd', 'slotAdd') fire once at the moment they are granted: an upgrade
 *     level bought, a know-how level bought, a decade completed, a sector's first Steady State. They are ignored on
 *     institutions (an institution is re-applied every run). 'reserveAdd', 'startCapitalMul' and 'startLever' are
 *     standing but act on the state at specific moments, as described per variant.
 * Unknown effect types are ignored.
 */
export type EffectDef =
  | { type: 'etaMul'; sector: SectorId; value: number }          // efficiency ×value
  | { type: 'capCostMul'; sector: SectorId; value: number }      // c ×value
  | { type: 'marginAdd'; sector: SectorId; value: number }       // m += value (negative = a royalty or premium; m floors at 0)
  /** 'stock': reserve and reserveMax += value × SectorDef.reserve, at run start (know-how, institution) or at
   *  purchase (upgrade); 'flow': capacity = SectorDef.reserve × (1 + Σ value), recomputed. */
  | { type: 'reserveAdd'; sector: SectorId; value: number }
  | { type: 'absorptionAdd'; sector: SectorId; value: number }   // absorption += value
  | { type: 'reveal' }                                           // sets flags.revealed (The Coal Question)
  | { type: 'startCapitalMul'; value: number }                   // know-how / institutions: run starts with startCapital ×value
  | { type: 'mandateRateMul'; value: number }                    // mandateRate ×value
  /** Institution: the lever starts each run at this level, free, and its levels up to `level` cost no Mandate and no
   *  upkeep (net upkeep = upkeep(current level) − upkeep(min(level, current level))). */
  | { type: 'startLever'; lever: string; level: number }
  | { type: 'costMul'; value: number }                           // all upgrade capital costs ×value
  /* --- M1 --- */
  | { type: 'satMul'; sector: SectorId; app?: string; value: number }       // saturation ×value (one app, or every app of the sector)
  | { type: 'halfPriceMul'; sector: SectorId; app?: string; value: number } // p_i ×value (> 1: adopted at higher prices = more demand)
  | { type: 'popGrowthMul'; value: number }                      // popGrowth ×value
  | { type: 'wellbeingAdd'; value: number }                      // flat wellbeing points added to W (before the ≥ 0 clamp)
  | { type: 'unlock'; id: string }                               // makes the `locked` upgrade or lever with this id available
  | { type: 'slotAdd'; value: number }                           // ONE-OFF: meta.slots += value
  | { type: 'mandateAdd'; value: number }                        // ONE-OFF: mandate += value
  | { type: 'capitalAdd'; value: number };                       // ONE-OFF: capital += value × current income per second

export interface UpgradeDef {
  id: string;              // 'steam.condenser'
  sector: SectorId;
  name: string;            // "Separate condenser"
  blurb: string;           // "Watt, 1769. Stop cooling the cylinder."
  /** 'efficiency' cards show the promise line; 'efficiency' and 'capital' cards show the projection lines. */
  kind: 'efficiency' | 'capital' | 'prospect' | 'research';
  /** Capital cost of the first purchase. */
  cost: number;
  /** For repeatable upgrades: cost of level n = cost × costGrowth^n (n = levels already owned). */
  repeatable?: boolean;
  costGrowth?: number;
  maxLevel?: number;
  /** Ids of upgrades that must be owned (level ≥ 1) first. Unknown ids are treated as unmet. */
  requires?: string[];
  /**
   * M1: forks. Ids of upgrades this one excludes for the rest of the run. Exclusion is symmetric: an upgrade is
   * excluded if any owned upgrade lists it, or it lists any owned upgrade. Excluded cards stay visible (so the fork
   * reads as a choice) but cannot be bought. Content should list both sides. Default: none.
   */
  excludes?: string[];
  /** M1: hidden and unbuyable unless a standing `unlock` effect names this id. Default false. */
  locked?: boolean;
  effects: EffectDef[];
}

export type LeverKind =
  /** Tax that holds the service price up as η rises. With strength s (0–0.999) and p the price before duty
   *  (pre-levy price + permit part):  dutyPart = s × max(0, p_ref − p), p_ref = p when the lever first went above 0
   *  (LeverState.ref). The strongest duty lever of a sector applies. Revenue = dutyPart × D (never player income). */
  | 'duty'
  /** M1 CHANGE: hard ceiling capR = value × budgetR(t) — a fraction of the sector's declining BUDGET LINE, not of
   *  "R when enacted". The tightest cap of a sector applies. If the sector has no budget when a cap is active, one is
   *  drawn at the current R on the first step with demand once the sector has been open steady.standingDrawYears
   *  (M1 balance; default 0); until then the cap has no line and does nothing. A permit price is added to p_r until R meets the cap.
   *  Leak: when permit > value2 × p_r (leakAbove), the effective cap rises by up to 25%:
   *    leak = 0.25 × clamp(permit / (leakAbove × p_r) − 1, 0, 1), solved self-consistently; value2 absent = no leak.
   *  Squeeze limit: a cap never squeezes out more than 95% of the demand above the floors (lock-in floors and drawsOn
   *  demand, which no price removes): effective target = max(capR × (1 + leak), R_floor + 0.05 × (R_free − R_floor)),
   *  R_free = R with no cap. Below that the cap is simply not met. Permit revenue = permit × R (never player income). */
  | 'cap'
  /** Saturation of the sector's applications drifts toward `value` × S_i at rate value2 per second (default 0.01):
   *  satMul −= (satMul − target) × (1 − exp(−rate × dt)). Relaxed, it recovers toward 1 at 0.01 per second. */
  | 'sufficiency'
  /** A share σ = min(value, value2 / D) of the service comes from a renewable flow: uses no resource, makes no
   *  pressure, costs 1.5 × c per unit (blended into the pre-levy price). value2 = flowCap in service units per second
   *  (absent = unlimited). Several substitution levers in one sector: shares add (≤ 1), flowCaps add. */
  | 'substitution'
  /** A share of resource used returns to the reserve ('stock' only): drain = R × (1 − share). Shares add, ≤ 0.95. */
  | 'circularity'
  /** Cuts this sector's indirect spill by a share. Shares add, ≤ 1. */
  | 'greenSpending'
  /** Code: spends `value` share of effective capacity (≤ 0.9) to shrink P at value2 (default 1) per unit capacity per second. */
  | 'deletion'
  /** Code: shipped service limited to reviewed service; removes `value` of the defect penalty and cuts D accordingly. */
  | 'reviewGate'
  /** Code: pressureIntensity × (1 − share). Shares add, ≤ 0.95. */
  | 'sharedLibs';

/**
 * M1: where a levy's revenue goes (meaningful for 'duty' and 'cap' only).
 *   'treasury': GlobalParams.levy.mandateShare of it becomes Mandate (v1 behaviour); the rest vanishes.
 *   'dividend': returned to households per head: counted as service in wellbeing (see SectorDef.wellbeingWeight); no
 *               Mandate. Wellbeing up means population up: an economy-wide rebound the card should name.
 * 'commons' is reserved for M2.
 */
export type LeverRecycle = 'treasury' | 'dividend';

export interface LeverDef {
  id: string;              // 'steam.duty'
  sector: SectorId;
  kind: LeverKind;
  name: string;            // "Fuel duty escalator"
  blurb: string;
  /** What the catch is, in the UI's words. Required (content lint). */
  catch: string;
  /** One entry per authored level (level 1 = index 0). Level 0 = off. */
  levels: LeverLevelDef[];
  /**
   * Visibility gates, all must hold. Each entry is one of:
   *   'revealed'        → flags.revealed;
   *   an upgrade id     → owned (level ≥ 1) this run;
   *   an institution id → SEATED this run (M1 CHANGE: was "owned");
   * any other string is treated as met (the content lint flags it).
   * Independently of `requires`, every lever is hidden until flags.revealed, unless a seated institution starts it
   * (startLever), and hidden while `locked` and not unlocked.
   */
  requires?: string[];
  /** M1: hidden and unusable unless a standing `unlock` effect names this id. Default false. */
  locked?: boolean;
  /**
   * M1: "Tighten" beyond the authored levels. With L = levels.length and last = levels[L − 1], level L + k (k ≥ 1) is:
   *   value = last.value + k × valueStep;  value2 = last.value2 (+ k × value2Step if given);
   *   mandateCost = last.mandateCost × costGrowth^k;  mandateUpkeep = last.mandateUpkeep × upkeepGrowth^k;
   *   label = `label` with {pct} = round(value × 100), {value} = value to 2 dp, {n} = level; default `${last.label} +k`.
   * A repeat level exists only while its value stays inside the kind's range (duty 0–0.999, cap 0.05–∞, sufficiency
   * 0.05–1, substitution/greenSpending/reviewGate 0–1, circularity/sharedLibs 0–0.95, deletion 0–0.9) and k ≤ maxSteps.
   * For a cap, valueStep is negative (each Tighten lowers the cap as a fraction of the budget). Default: no repeat.
   */
  repeat?: {
    valueStep: number;
    value2Step?: number;
    costGrowth: number;
    upkeepGrowth: number;
    maxSteps?: number;
    label?: string;
  };
  /** M1: recycle options offered for this lever's revenue ('duty'/'cap' only); the first is the default.
   *  Default: ['treasury']. */
  recycle?: LeverRecycle[];
}

export interface LeverLevelDef {
  /** One-off Mandate to reach this level from the one below. */
  mandateCost: number;
  /** Mandate per second while held at this level. If Mandate hits 0 the costliest-upkeep lever drops one level,
   *  repeatedly, until upkeep is covered. */
  mandateUpkeep: number;
  /** Meaning depends on kind: duty strength, cap fraction of the budget line, sufficiency target, substitution share,
   *  circularity share, greenSpending share, deletion share of capacity, reviewGate share, sharedLibs share. */
  value: number;
  /** Secondary knob: sufficiency rate, substitution flowCap, cap leakAbove, deletion rate. */
  value2?: number;
  /** Short label for the level button: "Hold price at 60%". */
  label: string;
}

/**
 * Permanent, bought with Hindsight, the tempting kind: makes runs faster and shorter.
 * M1: nodes form trees with tiers and exclusive forks. Efficiency nodes should carry a visible rebound side-effect
 * (satMul or halfPriceMul > 1) so "runs start faster and hit the wall sooner" is printed on the node.
 */
export interface KnowhowDef {
  id: string;
  name: string;
  blurb: string;
  /** Hindsight cost of level n = cost × costGrowth^n (n = levels already owned). */
  cost: number;
  costGrowth: number;
  maxLevel: number;
  /** Applied once per level owned (standing), or once per level bought (one-off effects). */
  effects: EffectDef[];
  /** M1: tree this node belongs to (UI groups by it). Default 'general'. */
  tree?: string;
  /** M1: row in the tree. A node of tier t ≥ 2 is visible and buyable only once some node of tier t − 1 in the same
   *  tree has level ≥ 1. Default 1. */
  tier?: number;
  /** M1: exclusive fork group. Once any node of a branch has level ≥ 1, every other node with the same branch id is
   *  excluded for good (no respec in M1). Default: none. */
  branch?: string;
}

/** M1: a further level of an institution. Its effects are added to those of the levels below. */
export interface InstitutionLevelDef {
  /** Hindsight to buy this level. */
  cost: number;
  effects: EffectDef[];
  /** One line saying what this level adds. */
  label?: string;
}

/**
 * Permanent, bought with Hindsight, the slow kind: counter-levers in place from the start.
 * M1 CHANGE: institutions have levels and act only while SEATED in the loadout (see ModelApi.setLoadout).
 */
export interface InstitutionDef {
  id: string;
  name: string;
  blurb: string;
  /** Hindsight cost of level 1 (unlocking it). */
  cost: number;
  requires?: string[];     // other institution ids (level ≥ 1)
  /** Effects of level 1. */
  effects: EffectDef[];
  /** M1: levels 2, 3… (nextLevels[0] is level 2). Default: none (a one-level institution). */
  nextLevels?: InstitutionLevelDef[];
  /** M1: loadout seats it occupies while seated. Default 1. */
  slots?: number;
}

export interface AchievementDef {
  id: 'jevonsWasRight' | 'degrowthByAccident' | 'steadyState' | 'firstReckoning' | 'backfire' | string;
  name: string;
  blurb: string;
  hidden?: boolean;
  /**
   * M1 (brought forward from M3): granted the first time this holds, checked at least once per real second of play.
   * Without `when`, only the five built-in ids above are granted, by the core's own rules (see ModelApi.tick);
   * any other id without `when` is never granted.
   */
  when?: Cond;
}

export type HeadlineKey =
  | 'appFounded' | 'appAvailable'
  | 'sectorOpened'    // M1 CHANGE: was 'eraOpened'
  | 'crisis' | 'collapse' | 'exhausted'
  | 'backfire'        // first time a sector's (direct) rebound passes 100% this run
  | 'reveal' | 'leverEnacted' | 'leverLapsed'
  | 'steadySector'    // M1 CHANGE: was 'steadyEra'. A sector reaches Steady State (once per sector per run)
  | 'steadyAll' | 'reckoning' | 'efficiency'
  /* --- M1 --- */
  | 'ageBegins'       // the first sector of an age opens (sectorOrder[0]'s age at run start does not fire it)
  | 'budgetDrawn'     // a budget line is drawn or redrawn for a sector
  | 'decade'          // a sector completes a decade within budget ({n} = decade number this run)
  | 'budgetBroken';   // a streak holding at least one completed decade ends

/* ------------------------------------------------------------------ */
/* STATE (serialisable, plain JSON)                                    */
/* ------------------------------------------------------------------ */

export interface GameState {
  version: number;
  seed: number;
  /** Seconds played this run. */
  time: number;
  capital: number;
  mandate: number;
  population: number;
  peakPopulation: number;
  /** Bought this run: upgrade id → level (1 for one-offs). */
  upgrades: Record<string, number>;
  /** lever id → state. */
  levers: Record<string, LeverState>;
  /** M1 CHANGE (was `eras`): one entry per sector in content, open or closed. */
  sectors: Record<SectorId, SectorState>;
  flags: {
    /** The Coal Question has been researched (or a seated institution reveals). */
    revealed: boolean;
    /** Overall Steady State reached this run. */
    won: boolean;
  };
  /**
   * Consecutive model years in which every OPEN sector has been decoupling (at least one open). Resets to 0 when any
   * open sector stops decoupling and when a sector opens. flags.won is set when EVERY sector in content.sectorOrder is
   * open and steadyYearsAll ≥ STEADY_STATE_YEARS (so the 50 years are always served with all of them open).
   */
  steadyYearsAll: number;
  news: NewsItem[];        // newest first, capped at 40
  /** Sampled every 5 s of run time, capped at 240 samples (older half thinned). */
  history: HistorySample[];
  run: RunStats;
  /** Survives a Reckoning. */
  meta: MetaState;
}

/**
 * M1: a sector's budget line. budgetR(t) = max(floor × r0, r0 × (1 − d)^((min(t, heldAt) − since) × YEARS_PER_SECOND / 10)),
 * d = the sector's decline per decade, floor = steady.budgetFloor (default 0), heldAt absent = ∞.
 * Drawn (when absent) by: drawBudget(); the player raising any lever of the sector (setLever; M1 balance: any raise,
 * not only from level 0, so Tightening a standing cap draws its line); or an active cap lever on the first step with
 * demand once the sector has been open steady.standingDrawYears. drawBudget() on a sector that has one REDRAWS it at
 * the current R and resets the sector's streak (steadyYears 0); decades already earned are kept.
 */
export interface BudgetState {
  /** R (per second) when drawn. */
  r0: number;
  /** Run time (seconds) when drawn. */
  since: number;
  /** Calendar year when drawn (for the ledger). */
  drawnYear: number;
  /**
   * M1 balance: run time at which the line stopped declining because the sector reached Steady State on it (its streak
   * crossed STEADY_STATE_YEARS). Absent while the line still declines. A redraw starts a new, declining line.
   */
  heldAt?: number;
}

/** M1 CHANGE (was EraState). */
export interface SectorState {
  open: boolean;
  /** Seconds since this sector opened (0 if closed). */
  openFor: number;
  /** Current efficiency including upgrades, knowhow and autoEta. */
  eta: number;
  /**
   * η at the moment baseR/baseD were recorded (run-start know-how included), so every run starts at etaFold 1.
   * The shadow solve freezes η here. 0 until the baseline is recorded.
   */
  etaAtBase: number;
  /** 'stock': remaining reserve. 'flow': current capacity. */
  reserve: number;
  /** Total reserve ever available this run (Q0 + additions) — the denominator for the gauge and the price. */
  reserveMax: number;
  pressure: number;
  /** Number of crisisAt thresholds already fired. */
  crisesFired: number;
  /** application id → state */
  apps: Record<string, AppState>;
  /** R and D on the first step the sector has demand (normally the moment it opens): the baseline for rFold and frontierFold. */
  baseR: number;
  baseD: number;
  /** p_s at the baseline (for spill). */
  basePs: number;
  /** Exponential moving average of R, time constant 60 s (cosmetic trend arrow only since M1). */
  smoothR: number;
  /** d(smoothR)/dt as a fraction of smoothR per model year. Negative = falling. Cosmetic since M1. */
  trendR: number;
  peakR: number;
  /** M1 CHANGE: the current decoupling streak in model years (see SectorDerived.decoupling); 0 when not decoupling. */
  steadyYears: number;
  /** The sector's direct rebound has exceeded 100% at some point this run. */
  backfired: boolean;
  /** M1: the budget line, or null if none drawn this run. */
  budget: BudgetState | null;
  /** M1: Σ D × dt × YEARS_PER_SECOND this run — service delivered in "unit·years" (e.g. hp·years). */
  serviceDelivered: number;
  /** M1: calendar year at which each decade within budget was completed this run (the decades ledger). */
  decadesWithin: number[];
}

export interface AppState {
  available: boolean;
  founded: boolean;
  /** Current saturation multiplier from sufficiency levers (starts 1). */
  satMul: number;
  /** Highest demand reached (for lock-in). */
  peakD: number;
}

export interface LeverState {
  /** May exceed levels.length when the lever has `repeat`. */
  level: number;
  /** Duty: p_ref, the price before duty when the lever first went from 0 to > 0 (0 until the sector has demand).
   *  M1 CHANGE: unused by caps (they follow the budget line). */
  ref: number;
  /** M1: chosen recycle option; absent = the lever's default (recycle[0] ?? 'treasury'). */
  recycle?: LeverRecycle;
}

export interface NewsItem {
  time: number;
  /** Calendar year (Derived.year) at the time, as an integer. */
  year: number;
  key: HeadlineKey;
  text: string;
  /** M1 CHANGE: was `era`. */
  sector?: SectorId;
}

export interface HistorySample {
  time: number;
  /** M1 CHANGE (was `eras`): sector id → [eta / etaAtBase, R / baseR]. Absent while the sector is closed. */
  sectors: Record<SectorId, [number, number]>;
  /** M1: sector id → budgetR / baseR at the sample time, for sectors with a budget. */
  budget?: Record<SectorId, number>;
  wellbeing: number;
}

export interface RunStats {
  peakWellbeing: number;
  /** M1 CHANGE: model years during which at least one sector was decoupling (informational). */
  decoupledYears: number;
  /** Sum of all resource used this run, per sector. */
  resourceUsed: Record<SectorId, number>;
  clicks: number;
  /** Sectors that reached Steady State during this run. */
  steadySectors: Record<SectorId, boolean>;
  /** M1: ∫ max(0, W − subsistence) d(model years). */
  wellbeingYears: number;
  /** M1: model years with W ≥ wellbeingTarget (ramps the unburnt Hindsight term). */
  yearsAtTarget: number;
  /** M1: decades within budget completed this run, all sectors. */
  budgetDecades: number;
  /** M1: sectors whose first-ever backfire (not in meta.backfiredSectors before) happened this run. */
  firstBackfires: Record<SectorId, boolean>;
}

export interface MetaState {
  hindsight: number;
  hindsightEarned: number;
  reckonings: number;
  knowhow: Record<string, number>;
  /** M1 CHANGE: institution id → level owned (≥ 1). Was boolean. */
  institutions: Record<string, number>;
  achievements: Record<string, boolean>;
  /** Sectors that have reached Steady State at least once. */
  steadySectors: Record<SectorId, boolean>;
  /** M1 CHANGE (was furthestEra, an index): sectors ever opened. */
  sectorsOpened: Record<SectorId, boolean>;
  /** Summary of the previous run for the Reckoning card. */
  lastRun?: RunSummary;
  totalSeconds: number;
  /** M1: loadout seats owned. Fresh meta: global.startingSlots ?? 2; raised by one-off slotAdd effects. */
  slots: number;
  /** M1: seated institution ids (each owned), Σ slots ≤ meta.slots. Changed only by setLoadout. */
  loadout: string[];
  /** M1: sectors that have ever backfired (for the first-backfire Hindsight award). */
  backfiredSectors: Record<SectorId, boolean>;
}

export interface RunSummary {
  cause: ReckoningCause;
  causeSector?: SectorId;
  seconds: number;
  /** Calendar year reached (integer). */
  yearReached: number;
  hindsightGained: number;
  peakWellbeing: number;
  /**
   * Per sector open at the end: how much more efficient, how much more resource per second at peak, resource used;
   * M1 adds share of reserve left ('stock' sectors only) and decades within budget.
   */
  sectors: Record<SectorId, {
    etaFold: number; peakRFold: number; resourceUsed: number; unburnt?: number; decades?: number;
  }>;
  /** M1: the Hindsight breakdown at the Reckoning. Absent on summaries migrated from v1. */
  hindsightTerms?: HindsightTerms;
}

export type ReckoningCause = 'exhausted' | 'collapse' | 'chosen';

/* ------------------------------------------------------------------ */
/* DERIVED (recomputed from state every frame, never stored)           */
/* ------------------------------------------------------------------ */

/** M1: the parts of ModelApi.hindsightOnReckon, for the Reckoning card. All weighted terms are ≥ 0. */
export interface HindsightTerms {
  /** Raw run.wellbeingYears. */
  wellbeingYears: number;
  /** Average burn fold of the run: Σ_s (resourceUsed_s / baseR_s) / Σ_s openFor_s over open sectors with baseR > 0 and
   *  openFor > 0 (unit-free); 1 if there are none. The formula uses max(1, intensity). */
  intensity: number;
  /** perWellbeingYear × wellbeingYears / max(1, intensity)^intensityExponent */
  wellbeing: number;
  /** perBudgetDecade × run.budgetDecades */
  budget: number;
  /** perUnburnt × Σ over open stock sectors of (reserve / reserveMax) × min(1, yearsAtTarget / STEADY_STATE_YEARS) */
  unburnt: number;
  /** perFirstBackfire × count of run.firstBackfires */
  backfire: number;
  /** perSectorReached × max(0, open sectors − 1) */
  sectorsReached: number;
  /** perSteadySector × count of run.steadySectors */
  steady: number;
  /** max(1, round(sum of the six weighted terms)) — equals hindsightOnReckon. */
  total: number;
}

/** M1: one line of a checklist built from a Cond. */
export interface CondCheck {
  /** Cond.label, or a plain fallback the core writes ("Own steam.condenser", "steam service delivered ≥ 40k"). */
  label: string;
  met: boolean;
  /** 0–1 for stat leaves (value/target for > and >=; target/value for < and <=), 1/0 for other leaves, null for combinators. */
  progress: number | null;
}

export interface Derived {
  /** M1 CHANGE: calendar year (see AgeDef.yearSpan), fractional. */
  year: number;
  /** M1: the current age: the last age in content.ages with an open sector (null only if content has no ages). */
  age: AgeId | null;
  wellbeing: number;                // 0–100-ish
  incomePerSec: number;
  /** M1: capital one click pays now: clickFlat + clickSeconds × incomePerSec (0 while a Reckoning is pending). */
  clickValue: number;
  mandatePerSec: number;            // net of lever upkeep, including treasury levy share
  /** dN/dt per second (see GlobalParams.popGrowth). */
  populationGrowthPerSec: number;
  /** A forced Reckoning is pending (model.tick stops advancing; UI must show the Reckoning screen). */
  pendingReckoning: { cause: ReckoningCause; sector?: SectorId } | null;
  hindsightIfReckonNow: number;
  /** M1: the breakdown of hindsightIfReckonNow. */
  hindsightTerms: HindsightTerms;
  /** M1 CHANGE (was `eras`): open sectors only. */
  sectors: Record<SectorId, SectorDerived>;
  /**
   * M1 CHANGE (was nextEra): the closed sectors whose `after` sectors are all open (the ones that could open next), in
   * sectorOrder, each with its unlock checklist; [] when none.
   * checklist: one CondCheck per child of unlock.when if it is an `all`, else one for `when` itself; for legacy content
   * (no `when`, prevServicePriceBelow set) one stat-style line on the predecessor's service price. Reckonings are
   * reported separately. ready = every condition including reckonings holds (it opens on the next step).
   */
  nextSectors: {
    id: SectorId; reckoningsNeeded: number; reckoningsHave: number; checklist: CondCheck[]; ready: boolean;
  }[];
  /**
   * M1: true while the run is untouched (time === 0 and no upgrade owned). Hindsight can be spent and the loadout
   * changed only then; the UI must not tick while the post-Reckoning screens are open.
   */
  freshRun: boolean;
  /** M1: loadout seats owned and in use. */
  slots: { total: number; used: number };
}

/** M1 CHANGE (was EraDerived). */
export interface SectorDerived {
  eta: number;
  /** eta / etaAtBase (1 before the baseline exists). */
  etaFold: number;
  /** p_r incl. permit price. */
  resourcePrice: number;
  /** M1: p_r without the permit (depletion or utilisation price). */
  resourcePriceBase: number;
  /** M1: permit price per unit of resource (0 unless a cap binds). */
  permitPrice: number;
  /** M1: effective capital cost c per unit of service (capCost × Π capCostMul). */
  capCost: number;
  /** M1: effective margin m. */
  margin: number;
  /** M1: substituted share σ (0 without substitution levers). */
  substitutedShare: number;
  /**
   * M1: the price before any levy: p_pre = (1 − σ) × (resourcePriceBase / η + c) + σ × 1.5 × c.
   * Player income = m × p_pre × D.
   */
  preLevyPrice: number;
  /** M1: permit part of the service price: (1 − σ) × permitPrice / η. */
  permitPart: number;
  /** M1: duty part of the service price (see LeverKind 'duty'). */
  dutyPart: number;
  /** p_s the customer pays: preLevyPrice + permitPart + dutyPart. */
  servicePrice: number;
  demand: number;                   // D, service per second
  resourceUse: number;              // R per second
  rFold: number;                    // R / baseR (1 before the baseline)
  /**
   * M1: the SHADOW: R this sector would burn right now with η frozen at etaAtBase, everything else identical (founded
   * applications, satMul, population, reserve and depletion price, spill and drawsOn inputs, levers, budget and cap).
   * "What this economy would burn with no efficiency gains at all." 0 before the baseline.
   */
  shadowR: number;
  /** M1 CHANGE: shadowR / etaFold — what the cards promised for today's economy. Was baseR / etaFold. */
  promisedR: number;
  /**
   * M1 CHANGE: DIRECT rebound, measured against the shadow:
   *   rebound = (R − promisedR) / (shadowR − promisedR)
   * Share of the promised savings eaten by extra use of the same applications; > 1 is backfire. New applications,
   * population and depletion move shadowR as well, so they no longer count. Under a binding cap R ≈ shadowR, so the
   * meter reads ≈ 100%: the savings became service, the cap set the coal. null until etaFold > 1.001, or while
   * shadowR ≤ 0 or shadowR − promisedR ≤ 1e−9 × shadowR.
   */
  rebound: number | null;
  /**
   * M1: shadowR / baseR — growth at frozen efficiency since the baseline: new applications (frontier), population
   * (economy-wide) and scarcity together. rFold = frontierFold × R / shadowR. 1 before the baseline.
   */
  frontierFold: number;
  income: number;
  /** M1: levy revenue per second (dutyPart × D + permitPrice × R); never income. */
  levyRevenue: number;
  /** 'stock': reserve / reserveMax. 'flow': 1 − utilisation. */
  reserveFraction: number;
  /** Seconds until exhaustion (reserve reaching EXHAUSTED_BELOW × reserveMax) at the current net drain ('stock'), Infinity otherwise. */
  secondsLeft: number;
  pressureFraction: number;         // P / collapseAt
  /** M1: the fraction of collapseAt at which the next crisis fires (crisisAt[crisesFired]), null once all have fired. */
  nextCrisisFraction: number | null;
  /** Cosmetic trend arrow (SectorState.trendR). */
  trendR: number;
  /** M1: today's budget line R, or null if no budget is drawn. */
  budgetR: number | null;
  /** M1: budget drawn and R ≤ budgetR × (1 + BUDGET_TOLERANCE). */
  withinBudget: boolean;
  /**
   * M1 CHANGE (one definition used everywhere): withinBudget AND wellbeing ≥ wellbeingTarget AND no Reckoning pending.
   * Replaces v1's "trendR < −0.001": a held line counts, short dips earn nothing unless a whole decade is served, and a
   * budget must be drawn before anything counts (efficiency-only play never decouples).
   */
  decoupling: boolean;
  /** Current streak in model years (SectorState.steadyYears). */
  steadyYears: number;
  /** M1: decades within budget completed this run (SectorState.decadesWithin.length). */
  budgetDecades: number;
  wellbeingShare: number;           // this sector's contribution to wellbeing
  apps: Record<string, AppDerived>;
}

export interface AppDerived {
  available: boolean;
  founded: boolean;
  demand: number;
  /** demand / current effective saturation, 0–1. */
  adoption: number;
  canFound: boolean;
}

export interface UpgradeView {
  def: UpgradeDef;
  level: number;
  /** Capital cost of the next purchase (after cost multipliers). */
  cost: number;
  /** Sector open, prerequisites met, and not locked. Excluded fork arms stay visible. */
  visible: boolean;
  /** Visible, not maxed, not excluded, and capital ≥ cost. */
  affordable: boolean;
  maxed: boolean;
  /** M1: id of the owned upgrade that excludes this one (fork already taken), else null. */
  excludedBy: string | null;
  /** Efficiency cards: the engineer's promise, 1 / Π etaMul − 1, e.g. −0.6 for "−60% coal per unit of power". */
  promisedChange: number | null;
  /**
   * M1 (replaces projectedChange): "This decade". For visible, unmaxed, unexcluded 'efficiency' and 'capital' cards,
   * once flags.revealed: simulate two clones PROJECTION_YEARS ahead (200 s, steps of 5 s; population, depletion and
   * availability all move; nothing else is bought, no app is founded), one with this upgrade applied free.
   *   projectedDecade = R_with / R_without − 1 for the upgrade's sector at the horizon (null if R_without ≤ 0).
   * Otherwise null.
   */
  projectedDecade: number | null;
  /**
   * M1: "Brings within reach". Same two simulations: every application of the upgrade's sector that is not yet
   * available now, whose visibleBelow the with-upgrade path's service price reaches within the horizon and the
   * without path's does not. projectedChange = R(with-upgrade end state, that app founded) / R(with-upgrade end state)
   * − 1, i.e. "+180% coal if founded". Ordered by visibleBelow descending. [] when projectedDecade is null.
   */
  bringsWithinReach: { appId: string; projectedChange: number }[];
}

export interface LeverView {
  def: LeverDef;
  level: number;
  /** M1: highest reachable level (levels.length, plus repeat steps; Infinity only if repeat has no bound at all). */
  maxLevel: number;
  /** M1: resolved definition of the current level (synthesised for repeat levels), null at level 0. */
  current: LeverLevelDef | null;
  /** M1: resolved definition of the next level, null at maxLevel. */
  next: LeverLevelDef | null;
  visible: boolean;
  /** Mandate needed for the next level (0 where an institution makes it free), null if at max. */
  nextCost: number | null;
  canRaise: boolean;
  /** Net Mandate upkeep per second at the current level. */
  upkeep: number;
  /** M1: options offered (empty for kinds other than duty and cap) and the one in force (null for those kinds). */
  recycleOptions: LeverRecycle[];
  recycle: LeverRecycle | null;
}

/** M1: one Know-how node for the Hindsight shop. */
export interface KnowhowView {
  def: KnowhowDef;
  level: number;
  /** Hindsight cost of the next level, null if maxed. */
  cost: number | null;
  /** Tier gate met (see KnowhowDef.tier). Excluded nodes still report true here. */
  requirementsMet: boolean;
  maxed: boolean;
  /** Id of the owned node in the same branch, if this one is excluded. */
  excludedBy: string | null;
  /** meta.hindsight ≥ cost (false when maxed). */
  affordable: boolean;
  /** requirementsMet, not maxed, not excluded, affordable, and Derived.freshRun. */
  canBuy: boolean;
}

/** M1: one Institution for the Hindsight shop and the loadout. */
export interface InstitutionView {
  def: InstitutionDef;
  /** Level owned (0 = not unlocked). */
  level: number;
  maxLevel: number;
  /** Hindsight for the next level (level 1 = def.cost), null at max. */
  nextCost: number | null;
  /** `requires` met. */
  requirementsMet: boolean;
  /** meta.hindsight ≥ nextCost (false at max). */
  affordable: boolean;
  seated: boolean;
  /** def.slots ?? 1 */
  slots: number;
  /** requirementsMet, below max, affordable, and Derived.freshRun. */
  canBuy: boolean;
  /** Owned, not seated, free seats ≥ slots, and Derived.freshRun. */
  canSeat: boolean;
}

/* ------------------------------------------------------------------ */
/* MODEL API                                                           */
/* ------------------------------------------------------------------ */

export interface ModelApi {
  /**
   * Fresh run. Pass the previous meta to carry Hindsight, know-how, institutions and the loadout over.
   * sectorOrder[0] opens at t = 0 with its free applications founded and its baseline recorded; seated institutions
   * and know-how apply (start capital, start reserves, start levers, reveal). A fresh meta has slots = startingSlots ?? 2.
   */
  createState(content: Content, meta?: MetaState, seed?: number): GameState;

  /**
   * Advance by dt seconds. dt is clamped to [0, MAX_TICK_SECONDS]; it is stepped in sub-steps of at most 1 s.
   * Each step (all open sectors, in sectorOrder): η, applications (availability, sufficiency drift, peaks), reserve,
   * pressure and crises, baseline, trend, serviceDelivered, backfire (direct rebound > 1, first time this run:
   * SectorState.backfired, 'backfire' headline and achievement, meta.backfiredSectors and run.firstBackfires if new),
   * budget auto-draw for active caps (after steady.standingDrawYears), decoupling streak (steadyYears += dt × YEARS_PER_SECOND while decoupling, else
   * reset — a reset of a streak holding ≥ 1 decade emits 'budgetBroken'; each time the streak crosses a multiple of
   * decadeYears a decade is recorded: decadesWithin, run.budgetDecades, decade effects, 'decade' headline; crossing
   * STEADY_STATE_YEARS holds the sector's budget line (BudgetState.heldAt) and sets run.steadySectors / meta.steadySectors, achievement 'steadyState', 'steadySector' headline
   * (once per sector per run) and, if the sector is new to meta.steadySectors, firstSteadyEffects); then population,
   * Mandate and lapses, sector unlocks ('sectorOpened', and 'ageBegins' when it is the first open sector of its age,
   * meta.sectorsOpened), steadyYearsAll and the win, run stats (wellbeingYears, yearsAtTarget, decoupledYears,
   * peakWellbeing), achievements with `when`. Built-in achievements: 'backfire' (above); 'jevonsWasRight' (every
   * efficiency upgrade of a sector that is not excluded by a fork owned, and peakR / baseR ≥ 10); 'degrowthByAccident'
   * (population < 0.6 × peak, some open sector with trendR < 0, wellbeing < target); 'steadyState' (above);
   * 'firstReckoning' (in reckon). Returns the same reference while a Reckoning is pending.
   */
  tick(state: GameState, content: Content, dt: number): GameState;
  /** Offline catch-up: steps of at most 5 s, capped at content.global.offlineCapSeconds, stops at a pending Reckoning. */
  fastForward(state: GameState, content: Content, seconds: number): GameState;

  derive(state: GameState, content: Content): Derived;

  /* --- player actions: each returns the new state, or the same reference if the action is not allowed --- */
  /** capital += Derived.clickValue; run.clicks++. */
  click(state: GameState, content: Content): GameState;
  /** Refused if not visible, maxed, excluded, unaffordable, or a Reckoning is pending. One-off effects fire. */
  buyUpgrade(state: GameState, content: Content, upgradeId: string): GameState;
  foundApp(state: GameState, content: Content, appId: string): GameState;
  /**
   * Raise or lower a lever to `level` (0 … maxLevel). Raising charges Mandate (levels at or below an institution's
   * startLever level are free); lowering is free and immediate. Raising a lever from 0 snapshots duty's ref; raising any
   * lever (M1 balance: from any level) draws the sector's budget at the current R if it has none.
   */
  setLever(state: GameState, content: Content, leverId: string, level: number): GameState;
  /** M1: choose where a duty or cap lever's revenue goes. Refused for options the lever does not offer. Free. */
  setLeverRecycle(state: GameState, content: Content, leverId: string, option: LeverRecycle): GameState;
  /**
   * M1: draw (or redraw) the sector's budget line at its current R. Requires flags.revealed, the sector open with R > 0,
   * and no pending Reckoning. Redrawing resets the sector's streak; earned decades are kept. Free. Emits 'budgetDrawn'.
   */
  drawBudget(state: GameState, content: Content, sector: SectorId): GameState;
  /** End the run. Uses the pending cause if there is one, else 'chosen'. Returns the fresh next run. */
  reckon(state: GameState, content: Content): GameState;
  /**
   * M1 CHANGE: allowed only while Derived.freshRun (between runs). Buys the next level of a node whose KnowhowView
   * reports canBuy. One-off effects (slotAdd) fire. The fresh run is rebuilt from the new meta (createState with the
   * same seed), keeping its news, Mandate, clicks and any capital earned by clicking.
   */
  buyKnowhow(state: GameState, content: Content, id: string): GameState;
  /** M1 CHANGE: buys the next level (level 1 unlocks). Allowed only while Derived.freshRun; rebuilds the run as buyKnowhow. */
  buyInstitution(state: GameState, content: Content, id: string): GameState;
  /**
   * M1: replace the loadout. Allowed only while Derived.freshRun. Refused unless every id is owned, ids are distinct,
   * and Σ slots ≤ meta.slots. Rebuilds the run as buyKnowhow.
   */
  setLoadout(state: GameState, content: Content, ids: string[]): GameState;

  /* --- views for the UI --- */
  /** Called about once a second and after each action; runs projections (the core caches them). */
  upgradeViews(state: GameState, content: Content): UpgradeView[];
  leverViews(state: GameState, content: Content): LeverView[];
  /** M1: the Hindsight shop, Know-how half (content order). */
  knowhowViews(state: GameState, content: Content): KnowhowView[];
  /** M1: the Hindsight shop, Institutions half, and the loadout (content order). */
  institutionViews(state: GameState, content: Content): InstitutionView[];
  /**
   * M1 CHANGE: Hindsight a Reckoning now would pay: HindsightTerms.total (see GlobalParams.hindsight). Reckoning adds
   * it to meta.hindsight and hindsightEarned, fills meta.lastRun (with hindsightTerms), reckonings++, grants
   * 'firstReckoning', and returns createState(content, newMeta, nextSeed) with a 'reckoning' headline.
   */
  hindsightOnReckon(state: GameState, content: Content): number;

  /* --- persistence --- */
  serialize(state: GameState): string;
  /** Returns null if the string is not a usable save. Migrates older versions (see SAVE_VERSION). */
  deserialize(text: string, content: Content): GameState | null;
}
